-- Coach Operations — Curriculum Library V2
-- Compact UI is delivered separately in CurriculumManager.tsx.
-- This migration enriches the shared ATOM curriculum without overwriting existing data.
--
-- Adds 10 new Blocks, 62 Techniques and curated Situations / opponent reactions.
-- Existing V1 rows are preserved; missing V2 rows only are inserted.
-- Situation names are unique only within their resolved Technique.

begin;

-- Guard Systems was introduced by Curriculum V1. Keep this migration resilient if
-- V2 is applied to an environment where the V1 seed was not run yet.
insert into public.coach_curriculum_types (
  name, slug, description, sort_order, is_active
)
select
  'Guard Systems',
  'guard-systems',
  'Guard positions, controls, sweeps, transitions and back-take systems.',
  25,
  true
where not exists (
  select 1
  from public.coach_curriculum_types t
  where lower(t.name) = lower('Guard Systems')
     or lower(t.slug) = lower('guard-systems')
);

do $atom_curriculum_v2_blocks$
declare
  v_seed jsonb := $json$[{"type":"Guard Systems","block":"Collar Sleeve Guard","block_sort":110,"description":"Collar-and-sleeve distance control, off-balancing, sweeps and submission entries.","techniques":[{"name":"Collar-Sleeve Control & Distance","level":"Beginner","sort":10},{"name":"Tripod Sweep","level":"Beginner","sort":20},{"name":"Sickle Sweep","level":"Beginner","sort":30},{"name":"Omoplata Entry","level":"Intermediate","sort":40},{"name":"Triangle Entry","level":"Intermediate","sort":50},{"name":"DLR Transition","level":"Intermediate","sort":60},{"name":"Back Take","level":"Intermediate","sort":70}]},{"type":"Guard Systems","block":"Lasso Guard","block_sort":120,"description":"Lasso-based control, off-balancing, sweeps, attacks and transitions.","techniques":[{"name":"Lasso Entry / Control","level":"Beginner","sort":10},{"name":"Lasso Sweep","level":"Beginner","sort":20},{"name":"Technical Stand-Up Sweep","level":"Intermediate","sort":30},{"name":"Omoplata Entry","level":"Intermediate","sort":40},{"name":"Triangle Entry","level":"Intermediate","sort":50},{"name":"Back Take","level":"Advanced","sort":60},{"name":"DLR Transition","level":"Intermediate","sort":70}]},{"type":"Guard Systems","block":"Reverse De La Riva","block_sort":130,"description":"Reverse De La Riva control, inversion, sweeps and back exposure.","techniques":[{"name":"RDLR Entry / Control","level":"Intermediate","sort":10},{"name":"Inversion Entry","level":"Intermediate","sort":20},{"name":"Kiss of the Dragon","level":"Advanced","sort":30},{"name":"RDLR Sweep","level":"Intermediate","sort":40},{"name":"Single Leg Transition","level":"Intermediate","sort":50},{"name":"Back Take","level":"Advanced","sort":60}]},{"type":"Guard Systems","block":"Single Leg X","block_sort":140,"description":"Single Leg X control, sweeps and transitions to standing or X Guard.","techniques":[{"name":"SLX Entry","level":"Beginner","sort":10},{"name":"Inside Sweep","level":"Beginner","sort":20},{"name":"Outside Sweep","level":"Intermediate","sort":30},{"name":"Technical Stand-Up Sweep","level":"Beginner","sort":40},{"name":"X Guard Transition","level":"Intermediate","sort":50},{"name":"Back Take Transition","level":"Advanced","sort":60}]},{"type":"Guard Systems","block":"X Guard","block_sort":150,"description":"X Guard off-balancing, sweeps and transitions against a standing opponent.","techniques":[{"name":"X Guard Entry","level":"Intermediate","sort":10},{"name":"Technical Stand-Up Sweep","level":"Intermediate","sort":20},{"name":"Back Sweep","level":"Intermediate","sort":30},{"name":"Side Sweep","level":"Intermediate","sort":40},{"name":"Single Leg Finish","level":"Intermediate","sort":50},{"name":"Back Take","level":"Advanced","sort":60}]},{"type":"Escapes","block":"Turtle Escapes / Recovery","block_sort":40,"description":"Safe escapes, guard recovery and counter-wrestling from turtle.","techniques":[{"name":"Sit-Out Escape","level":"Beginner","sort":10},{"name":"Granby Roll","level":"Intermediate","sort":20},{"name":"Guard Recovery","level":"Beginner","sort":30},{"name":"Single Leg Recovery","level":"Intermediate","sort":40},{"name":"Peterson Roll","level":"Intermediate","sort":50},{"name":"Back Exposure Prevention","level":"Beginner","sort":60}]},{"type":"Submissions","block":"Front Headlock","block_sort":20,"description":"Front headlock control, chokes and positional transitions.","techniques":[{"name":"Front Headlock Control","level":"Beginner","sort":10},{"name":"Guillotine","level":"Beginner","sort":20},{"name":"Arm-In Guillotine","level":"Intermediate","sort":30},{"name":"Anaconda Choke","level":"Intermediate","sort":40},{"name":"D'Arce Choke","level":"Intermediate","sort":50},{"name":"Go Behind","level":"Beginner","sort":60},{"name":"Back Take Transition","level":"Intermediate","sort":70}]},{"type":"Submissions","block":"Side Control Attacks","block_sort":30,"description":"Control and submission chains from side control.","techniques":[{"name":"Crossface Control","level":"Beginner","sort":10},{"name":"Americana","level":"Beginner","sort":20},{"name":"Kimura","level":"Beginner","sort":30},{"name":"Armbar","level":"Intermediate","sort":40},{"name":"Paper Cutter Choke","level":"Intermediate \u00b7 Gi","sort":50},{"name":"North-South Transition","level":"Beginner","sort":60}]},{"type":"Submissions","block":"Mount Attacks","block_sort":40,"description":"Mount control, pressure and submission chains.","techniques":[{"name":"Mount Control","level":"Beginner","sort":10},{"name":"Americana","level":"Beginner","sort":20},{"name":"Cross-Collar Choke","level":"Beginner \u00b7 Gi","sort":30},{"name":"Ezekiel Choke","level":"Intermediate \u00b7 Gi","sort":40},{"name":"Armbar","level":"Beginner","sort":50},{"name":"S-Mount Armbar","level":"Intermediate","sort":60}]},{"type":"Submissions","block":"North-South Attacks","block_sort":50,"description":"North-South control, submission attacks and transitions.","techniques":[{"name":"North-South Control","level":"Beginner","sort":10},{"name":"North-South Choke","level":"Intermediate","sort":20},{"name":"Kimura","level":"Intermediate","sort":30},{"name":"Armbar Transition","level":"Intermediate","sort":40},{"name":"Back Take Transition","level":"Advanced","sort":50}]}]$json$::jsonb;
  v_block jsonb;
  v_technique jsonb;
  v_type_id uuid;
  v_block_id uuid;
  v_type_name text;
  v_block_name text;
  v_block_description text;
  v_technique_name text;
  v_level text;
  v_block_sort integer;
  v_technique_sort integer;
begin
  for v_block in select value from jsonb_array_elements(v_seed) loop
    v_type_name := btrim(v_block ->> 'type');
    v_block_name := btrim(v_block ->> 'block');
    v_block_description := nullif(btrim(v_block ->> 'description'), '');
    v_block_sort := coalesce((v_block ->> 'block_sort')::integer, 100);

    select t.id into v_type_id
    from public.coach_curriculum_types t
    where lower(t.name) = lower(v_type_name)
    order by t.is_active desc, t.created_at asc
    limit 1;

    if v_type_id is null then
      raise exception 'ATOM Curriculum V2 seed failed: technical type "%" was not found.', v_type_name;
    end if;

    select b.id into v_block_id
    from public.coach_curriculum_blocks b
    where b.type_id = v_type_id
      and lower(b.name) = lower(v_block_name)
    order by b.is_active desc, b.created_at asc
    limit 1;

    if v_block_id is null then
      insert into public.coach_curriculum_blocks (
        type_id, name, description, sort_order, is_active
      ) values (
        v_type_id, v_block_name, v_block_description, v_block_sort, true
      ) returning id into v_block_id;
    end if;

    for v_technique in select value from jsonb_array_elements(v_block -> 'techniques') loop
      v_technique_name := btrim(v_technique ->> 'name');
      v_level := btrim(v_technique ->> 'level');
      v_technique_sort := coalesce((v_technique ->> 'sort')::integer, 100);

      if not exists (
        select 1
        from public.coach_curriculum_techniques ct
        where ct.block_id = v_block_id
          and lower(ct.name) = lower(v_technique_name)
      ) then
        insert into public.coach_curriculum_techniques (
          block_id, name, description, sort_order, is_active
        ) values (
          v_block_id,
          v_technique_name,
          'ATOM Curriculum V2 · ' || v_level,
          v_technique_sort,
          true
        );
      end if;
    end loop;
  end loop;
end
$atom_curriculum_v2_blocks$;

do $atom_curriculum_v2_situations$
declare
  v_seed jsonb := $json$[{"type":"Guard Systems","block":"Sit Up Guard","technique":"Sit Up Sleeve","name":"Standing square","reaction":"Opponent stands square and keeps hips back.","response":"Keep sleeve connection, sit tall and create an angle before entering the sweep or single leg.","sort":10},{"type":"Guard Systems","block":"Sit Up Guard","technique":"Sit Up Sleeve","name":"Opponent steps backward","reaction":"Opponent retreats the controlled-side leg to remove your forward pressure.","response":"Follow with the sit-up connection and convert the distance into a technical stand-up or single-leg entry.","sort":20},{"type":"Guard Systems","block":"Sit Up Guard","technique":"Sit Up Sleeve","name":"Opponent drives forward","reaction":"Opponent closes distance and drives weight into you.","response":"Use the sleeve connection to redirect the pressure, frame with posture and create the next angle.","sort":30},{"type":"Guard Systems","block":"Sit Up Guard","technique":"Sit Up Sleeve","name":"Posting hand controlled","reaction":"Opponent controls or pins your free posting hand.","response":"Recover your post, switch the angle and keep the sleeve connection before attacking again.","sort":40},{"type":"Guard Systems","block":"Sit Up Guard","technique":"Sit Up Sleeve","name":"Sleeve grip breaks","reaction":"Opponent strips the sleeve grip and starts disengaging.","response":"Reconnect immediately or transition to lapel, belt or leg control instead of chasing the broken grip.","sort":50},{"type":"Guard Systems","block":"Sit Up Guard","technique":"Sit Up Sleeve","name":"Opponent drops to one knee","reaction":"Opponent lowers the base to one knee to deny the standing sweep.","response":"Change angle and connect to the near leg for a single-leg or guard transition.","sort":60},{"type":"Guard Systems","block":"Sit Up Guard","technique":"Sit Up Lasso","name":"Opponent pressures forward","reaction":"Opponent drives chest and knee pressure into the lasso side.","response":"Keep the lasso frame active, redirect the pressure and create an angle for the sweep or omoplata line.","sort":10},{"type":"Guard Systems","block":"Sit Up Guard","technique":"Sit Up Lasso","name":"Opponent circles outside","reaction":"Opponent circles away from the lasso side to square the hips.","response":"Follow the rotation with the lasso connection and re-angle before the opponent clears the leg.","sort":20},{"type":"Guard Systems","block":"Sit Up Guard","technique":"Sit Up Lasso","name":"Opponent strips the lasso","reaction":"Opponent peels the lasso grip or clears the leg.","response":"Recover sleeve control early and transition to Sit Up Sleeve, DLR or another connected guard.","sort":30},{"type":"Guard Systems","block":"Sit Up Guard","technique":"Sit Up Lapel","name":"Opponent stands tall","reaction":"Opponent straightens posture to reduce lapel pressure.","response":"Keep the lapel line connected and use the increased space to sit up and attack the base.","sort":10},{"type":"Guard Systems","block":"Sit Up Guard","technique":"Sit Up Lapel","name":"Opponent retreats and frees lapel","reaction":"Opponent steps away while working the lapel free.","response":"Follow the retreat, shorten the lapel connection and switch to leg or sleeve control before full disengagement.","sort":20},{"type":"Guard Systems","block":"Sit Up Guard","technique":"Sit Up Lapel Lasso","name":"Opponent drives forward","reaction":"Opponent pressures into the combined lapel-lasso structure.","response":"Use the lasso as the frame and lapel as the anchor to redirect the pressure and expose an angle.","sort":10},{"type":"Guard Systems","block":"Sit Up Guard","technique":"Sit Up Lapel Lasso","name":"Opponent circles away","reaction":"Opponent circles outside to unwind the lasso and lapel alignment.","response":"Follow with the hips, maintain the anchor and re-square the lasso before attacking.","sort":20},{"type":"Guard Systems","block":"Sit Up Guard","technique":"Sit Up Lapel Lasso","name":"Opponent posts a hand","reaction":"Opponent posts the free hand to stop the sweep.","response":"Use the post to open the shoulder line and transition to omoplata, back exposure or a secondary sweep.","sort":30},{"type":"Guard Systems","block":"Sit Up Guard","technique":"Sit Up Lapel Lasso","name":"Opponent stands tall","reaction":"Opponent extends posture and lifts the hips away from your hooks.","response":"Sit up behind the lapel connection and attack the base with a technical stand-up or leg entry.","sort":40},{"type":"Guard Systems","block":"Sit Up Guard","technique":"Sit Up Lapel Lasso","name":"Opponent disengages hips","reaction":"Opponent backs the hips away and attempts to clear both controls.","response":"Follow the distance, keep one reliable connection and transition before both grips are lost.","sort":50},{"type":"Guard Systems","block":"Sit Up Guard","technique":"Sit Up Belt","name":"Opponent squares hips","reaction":"Opponent turns the hips square to reduce the pulling angle on the belt.","response":"Re-angle your hips and use the belt connection to expose the near leg or off-balance the base.","sort":10},{"type":"Guard Systems","block":"Sit Up Guard","technique":"Sit Up Belt","name":"Opponent steps backward","reaction":"Opponent retreats to remove your sit-up pressure.","response":"Follow the belt connection and convert the retreat into a stand-up or single-leg attack.","sort":20},{"type":"Guard Systems","block":"Sit Up Guard","technique":"Sit Up Belt","name":"Opponent drives knee forward","reaction":"Opponent pushes the near knee forward to crowd your hip line.","response":"Frame, keep the belt anchor and angle outside the knee before attacking the base.","sort":30},{"type":"Guard Systems","block":"De La Riva","technique":"DLR Entry / Control","name":"Opponent strips ankle control","reaction":"Opponent peels your ankle grip and starts clearing the DLR hook.","response":"Reconnect the ankle before chasing upper-body grips, or transition to a connected open-guard position.","sort":10},{"type":"Guard Systems","block":"De La Riva","technique":"Tripod Sweep","name":"Opponent steps the lead foot back","reaction":"Opponent retracts the leg you want to control for the tripod sweep.","response":"Follow the foot, keep upper-body distance control and switch the sweep angle or enter a technical stand-up.","sort":10},{"type":"Guard Systems","block":"De La Riva","technique":"DLR Back Take","name":"Opponent squares the hips","reaction":"Opponent turns the hips square to deny the back angle.","response":"Maintain the DLR connection, off-balance again and re-create the outside hip angle before climbing to the back.","sort":10},{"type":"Guard Systems","block":"Deep De La Riva","technique":"Deep DLR Entry","name":"Opponent turns the knee outward","reaction":"Opponent externally rotates the knee to block your deep hook.","response":"Off-balance first, open the knee line and enter deep only after the weight shifts.","sort":10},{"type":"Guard Systems","block":"Deep De La Riva","technique":"Deep DLR Sweep","name":"Opponent posts the far hand","reaction":"Opponent posts the far hand to stop the sweep rotation.","response":"Use the post to extend the base and switch to the back-take or X-Guard transition.","sort":10},{"type":"Guard Systems","block":"Shallow Guard","technique":"Shallow Guard Entry","name":"Opponent keeps long distance","reaction":"Opponent keeps the hips far away and denies your preferred connection.","response":"Use upper-body connection to close distance safely before committing the shallow hook.","sort":10},{"type":"Guard Systems","block":"Shallow Guard","technique":"Technical Stand-Up Sweep","name":"Opponent retreats during stand-up","reaction":"Opponent steps backward as you rise for the sweep.","response":"Keep the connection and continue into the single-leg line rather than reaching from distance.","sort":10},{"type":"Guard Systems","block":"Waiter Guard","technique":"Waiter Entry","name":"Opponent hides the far leg","reaction":"Opponent retracts or turns the far leg away from the waiter entry.","response":"Control the near leg first and off-balance before searching for the far-leg connection.","sort":10},{"type":"Guard Systems","block":"Waiter Guard","technique":"Waiter Sweep","name":"Opponent posts a hand","reaction":"Opponent posts the hand to stop the waiter sweep.","response":"Use the post to extend the shoulder and transition to X Guard or the back angle.","sort":10},{"type":"Guard Systems","block":"Double Pull / Berimbolo","technique":"Double Pull Entry","name":"Opponent sits first","reaction":"Opponent wins the race to sit and establishes the first guard connection.","response":"Protect inside position, establish your own connection and only then enter the double-pull exchange.","sort":10},{"type":"Guard Systems","block":"Double Pull / Berimbolo","technique":"Berimbolo Entry","name":"Opponent blocks the inversion","reaction":"Opponent keeps the knee and hip tight to stop your inversion path.","response":"Create off-balance and hip separation before re-entering the inversion; do not force rotation into a closed space.","sort":10},{"type":"Guard Systems","block":"Deep Half Guard","technique":"Deep Half Entry","name":"Opponent applies crossface pressure","reaction":"Opponent controls the head and turns your face away during the deep-half entry.","response":"Protect head position first, reconnect under the hips and enter only after the crossface pressure is neutralized.","sort":10},{"type":"Guard Systems","block":"Deep Half Guard","technique":"Homer Simpson Sweep","name":"Opponent widens the base","reaction":"Opponent spreads the knees and posts weight to stop the rotation.","response":"Stay connected under the center of gravity and switch the sweep direction as the base widens.","sort":10},{"type":"Passing","block":"Under-Over Passing","technique":"Under-Over Entry","name":"Opponent frames the shoulders","reaction":"Opponent frames your upper body and prevents chest-to-hip connection.","response":"Clear or redirect the frame before settling the under-over position.","sort":10},{"type":"Passing","block":"Under-Over Passing","technique":"Under-Over Finish","name":"Opponent turns the knee inward","reaction":"Opponent turns the near knee inward to block your finishing angle.","response":"Keep shoulder pressure, control the hip line and change the finish angle instead of forcing forward.","sort":10},{"type":"Passing","block":"Open Guard Passing","technique":"Toreando","name":"Opponent recovers the feet","reaction":"Opponent pummels the feet back inside as you circle the legs.","response":"Keep distance on the legs, change direction and re-clear the knee line before closing chest distance.","sort":10},{"type":"Passing","block":"Open Guard Passing","technique":"Knee Cut","name":"Opponent frames shoulder and knee","reaction":"Opponent frames your shoulder and blocks the cutting knee with the near-side structure.","response":"Win crossface or underhook position first, then reconnect the knee-cut line.","sort":10},{"type":"Escapes","block":"Side Control Escapes","technique":"Frames + Hip Escape","name":"Opponent follows the hips","reaction":"Opponent tracks your hip movement and closes the space after the first shrimp.","response":"Rebuild the frames and make a second movement rather than trying to recover guard in one motion.","sort":10},{"type":"Escapes","block":"Mount Escapes","technique":"Upa / Bridge Escape","name":"Opponent posts the hand","reaction":"Opponent posts the free hand to stop the bridge-and-roll direction.","response":"Use the post to change the angle, trap the new side or connect immediately to the elbow escape.","sort":10},{"type":"Escapes","block":"Back Escapes","technique":"Safe Side Escape","name":"Opponent controls the choking hand","reaction":"Opponent keeps the choking-side hand protected while maintaining seatbelt control.","response":"Prioritize two-on-one hand control, put the shoulders on the safe side and clear the lower hook before turning.","sort":10},{"type":"Submissions","block":"Back Attacks","technique":"Rear Naked Choke","name":"Opponent tucks the chin","reaction":"Opponent hides the neck by tucking the chin and controlling the choking arm.","response":"Maintain chest-to-back control, win hand fighting and open the neck without forcing through the jaw.","sort":10},{"type":"Guard Systems","block":"Collar Sleeve Guard","technique":"Collar-Sleeve Control & Distance","name":"Opponent breaks posture upward","reaction":"Opponent straightens posture and pulls the upper body away.","response":"Keep collar-sleeve tension, manage distance with the feet and rebuild the attacking angle.","sort":10},{"type":"Guard Systems","block":"Collar Sleeve Guard","technique":"Tripod Sweep","name":"Opponent widens the stance","reaction":"Opponent spreads the feet to increase base against the tripod sweep.","response":"Control one ankle, extend the opposite hip line and attack the narrower side of the base.","sort":20},{"type":"Guard Systems","block":"Collar Sleeve Guard","technique":"Sickle Sweep","name":"Opponent retracts the near foot","reaction":"Opponent pulls the near foot away from your hook and sleeve line.","response":"Follow the foot with distance control and switch to tripod, DLR or technical stand-up.","sort":30},{"type":"Guard Systems","block":"Collar Sleeve Guard","technique":"Omoplata Entry","name":"Opponent drives the elbow inside","reaction":"Opponent pulls the controlled elbow tight to the ribs to deny shoulder exposure.","response":"Create angle with the collar-sleeve frame before threading the leg over the shoulder.","sort":40},{"type":"Guard Systems","block":"Collar Sleeve Guard","technique":"Triangle Entry","name":"Opponent keeps both elbows tight","reaction":"Opponent closes the elbow line and prevents one arm from being isolated.","response":"Off-balance first and force one hand to post before entering the triangle.","sort":50},{"type":"Guard Systems","block":"Collar Sleeve Guard","technique":"DLR Transition","name":"Opponent steps the controlled leg forward","reaction":"Opponent advances the controlled-side leg and squares the hip.","response":"Use the forward step to establish the DLR hook before the opponent settles weight.","sort":60},{"type":"Guard Systems","block":"Collar Sleeve Guard","technique":"Back Take","name":"Opponent turns away from collar pressure","reaction":"Opponent rotates the shoulders away to relieve collar-sleeve tension.","response":"Follow the turn, control the far hip and occupy the back angle before the opponent re-squares.","sort":70},{"type":"Guard Systems","block":"Lasso Guard","technique":"Lasso Entry / Control","name":"Opponent pulls the sleeve backward","reaction":"Opponent retracts the controlled arm to stop the lasso from wrapping.","response":"Use posture and hip angle to follow the sleeve before threading the lasso.","sort":10},{"type":"Guard Systems","block":"Lasso Guard","technique":"Lasso Sweep","name":"Opponent bases wide","reaction":"Opponent widens the knees and feet to resist the sweep direction.","response":"Stretch the lasso side, remove one post and attack the narrowed direction.","sort":20},{"type":"Guard Systems","block":"Lasso Guard","technique":"Technical Stand-Up Sweep","name":"Opponent retreats","reaction":"Opponent steps away as you begin the technical stand-up.","response":"Maintain sleeve connection and continue into a single-leg or ankle-control finish.","sort":30},{"type":"Guard Systems","block":"Lasso Guard","technique":"Omoplata Entry","name":"Opponent pressures the lasso side","reaction":"Opponent drives weight into the lasso shoulder to flatten you.","response":"Redirect the pressure, create shoulder separation and rotate under the exposed arm.","sort":40},{"type":"Guard Systems","block":"Lasso Guard","technique":"Triangle Entry","name":"Opponent posts the free hand","reaction":"Opponent posts the non-lasso hand to stop the off-balance.","response":"Use the post to isolate the arm line and close the triangle angle.","sort":50},{"type":"Guard Systems","block":"Lasso Guard","technique":"Back Take","name":"Opponent turns the lasso shoulder away","reaction":"Opponent rotates away to relieve shoulder pressure from the lasso.","response":"Follow the shoulder turn and climb to the back before the elbow clears.","sort":60},{"type":"Guard Systems","block":"Lasso Guard","technique":"DLR Transition","name":"Opponent clears the lasso leg","reaction":"Opponent circles the knee free of the lasso but leaves the lead leg close.","response":"Keep sleeve control and immediately replace the leg connection with DLR.","sort":70},{"type":"Guard Systems","block":"Reverse De La Riva","technique":"RDLR Entry / Control","name":"Opponent drives knee-cut pressure","reaction":"Opponent steps into a knee-cut stance and turns the knee toward your hip.","response":"Establish the reverse hook, frame the upper body and manage the knee line before attacking.","sort":10},{"type":"Guard Systems","block":"Reverse De La Riva","technique":"Inversion Entry","name":"Opponent lowers the hip","reaction":"Opponent drops weight toward your hips to block the inversion space.","response":"Create distance with the frame and invert only after the hip line becomes light.","sort":20},{"type":"Guard Systems","block":"Reverse De La Riva","technique":"Kiss of the Dragon","name":"Opponent squares during inversion","reaction":"Opponent rotates the hips square to stop you from coming behind.","response":"Stay attached to the leg, continue the rotation and control the far hip before rising.","sort":30},{"type":"Guard Systems","block":"Reverse De La Riva","technique":"RDLR Sweep","name":"Opponent posts the far leg","reaction":"Opponent steps the far leg wide to stop the sweep direction.","response":"Control the posting leg or switch to the opposite sweep angle.","sort":40},{"type":"Guard Systems","block":"Reverse De La Riva","technique":"Single Leg Transition","name":"Opponent retracts the trapped leg","reaction":"Opponent pulls the RDLR leg backward during your rise.","response":"Follow with upper-body connection and switch the grip before the leg fully escapes.","sort":50},{"type":"Guard Systems","block":"Reverse De La Riva","technique":"Back Take","name":"Opponent turns to face you","reaction":"Opponent rotates the torso back toward you as you expose the back.","response":"Control the hip line first and secure one hook before chasing upper-body control.","sort":60},{"type":"Guard Systems","block":"Single Leg X","technique":"SLX Entry","name":"Opponent keeps the knee line far","reaction":"Opponent retracts the leg and prevents your hips from connecting under the knee.","response":"Off-balance first and enter only when the leg becomes light enough to bring the knee line over your hips.","sort":10},{"type":"Guard Systems","block":"Single Leg X","technique":"Inside Sweep","name":"Opponent posts the free foot wide","reaction":"Opponent widens the free leg to stop the inside sweep.","response":"Control the ankle or switch the angle toward the outside sweep.","sort":20},{"type":"Guard Systems","block":"Single Leg X","technique":"Outside Sweep","name":"Opponent turns the knee inward","reaction":"Opponent internally rotates the trapped leg and shifts weight forward.","response":"Maintain hip connection and redirect the rotation into the technical stand-up or X Guard.","sort":30},{"type":"Guard Systems","block":"Single Leg X","technique":"Technical Stand-Up Sweep","name":"Opponent hops backward","reaction":"Opponent balances on the trapped leg and hops away as you stand.","response":"Keep the ankle elevated, follow the hops and finish the stand-up with posture.","sort":40},{"type":"Guard Systems","block":"Single Leg X","technique":"X Guard Transition","name":"Opponent drops the free knee","reaction":"Opponent lowers the free knee to close the space required for X Guard.","response":"Create a second off-balance and insert the far hook before extending.","sort":50},{"type":"Guard Systems","block":"Single Leg X","technique":"Back Take Transition","name":"Opponent turns away to free the knee","reaction":"Opponent rotates away from the trapped leg and exposes the hip line.","response":"Follow the hip rotation and connect behind the pelvis before releasing the leg.","sort":60},{"type":"Guard Systems","block":"X Guard","technique":"X Guard Entry","name":"Opponent keeps a staggered stance","reaction":"Opponent keeps one leg far behind and denies a square entry.","response":"Enter under the lead leg and angle the hooks before extending the base.","sort":10},{"type":"Guard Systems","block":"X Guard","technique":"Technical Stand-Up Sweep","name":"Opponent retracts the far leg","reaction":"Opponent pulls the far leg away as you start to rise.","response":"Keep the near leg controlled and finish into a single-leg rather than reaching for the far ankle.","sort":20},{"type":"Guard Systems","block":"X Guard","technique":"Back Sweep","name":"Opponent leans forward","reaction":"Opponent shifts the chest forward to prevent being loaded backward.","response":"Use the forward weight to change the extension angle and expose the side sweep or stand-up.","sort":30},{"type":"Guard Systems","block":"X Guard","technique":"Side Sweep","name":"Opponent bases with the far hand","reaction":"Opponent posts the far hand as the hips are turned sideways.","response":"Control the posting side and continue the hip extension before coming on top.","sort":40},{"type":"Guard Systems","block":"X Guard","technique":"Single Leg Finish","name":"Opponent whizzers after you stand","reaction":"Opponent applies a whizzer while balancing on the free leg.","response":"Keep head posture, control the knee line and finish with safe wrestling mechanics.","sort":50},{"type":"Guard Systems","block":"X Guard","technique":"Back Take","name":"Opponent turns the knee away","reaction":"Opponent rotates the trapped knee outward and exposes the back of the hip.","response":"Follow the hip line, connect behind the pelvis and secure control before releasing X Guard.","sort":60},{"type":"Escapes","block":"Turtle Escapes / Recovery","technique":"Sit-Out Escape","name":"Opponent controls the near arm","reaction":"Opponent clamps the near arm while staying heavy behind the shoulders.","response":"Create elbow space first, sit the hip through and turn to face before extending away.","sort":10},{"type":"Escapes","block":"Turtle Escapes / Recovery","technique":"Granby Roll","name":"Opponent follows behind the hips","reaction":"Opponent stays connected behind the hips and blocks a simple guard turn-in.","response":"Protect the neck, create shoulder space and roll through the open side to recover guard.","sort":20},{"type":"Escapes","block":"Turtle Escapes / Recovery","technique":"Guard Recovery","name":"Opponent circles toward the back","reaction":"Opponent circles around the turtle to expose the far hip.","response":"Track the movement with the near elbow-knee connection and insert guard before the back is secured.","sort":30},{"type":"Escapes","block":"Turtle Escapes / Recovery","technique":"Single Leg Recovery","name":"Opponent stands over turtle","reaction":"Opponent rises above the hips and leaves one leg within reach.","response":"Build posture safely, connect to the near leg and recover through a single-leg position.","sort":40},{"type":"Escapes","block":"Turtle Escapes / Recovery","technique":"Peterson Roll","name":"Opponent drives weight over one shoulder","reaction":"Opponent commits chest pressure diagonally over the near shoulder.","response":"Trap the driving side and use the committed weight to initiate the roll.","sort":50},{"type":"Escapes","block":"Turtle Escapes / Recovery","technique":"Back Exposure Prevention","name":"Opponent inserts the first hook","reaction":"Opponent establishes one hook and starts seatbelt control.","response":"Protect the neck, put the trapped hip to the mat and clear the hook before turning.","sort":60},{"type":"Submissions","block":"Front Headlock","technique":"Front Headlock Control","name":"Opponent keeps strong base on both knees","reaction":"Opponent stays square on the knees and resists being pulled forward.","response":"Control chin and elbow line, angle off and create movement before attacking the neck.","sort":10},{"type":"Submissions","block":"Front Headlock","technique":"Guillotine","name":"Opponent drives forward","reaction":"Opponent continues forward pressure into your hips while defending the neck.","response":"Keep the choking elbow position, manage distance with the legs and finish only after controlling posture.","sort":20},{"type":"Submissions","block":"Front Headlock","technique":"Arm-In Guillotine","name":"Opponent hides the neck with the arm inside","reaction":"Opponent keeps the near arm tight and uses it to protect the neck line.","response":"Use the arm-in configuration to control shoulder posture before closing the choke.","sort":30},{"type":"Submissions","block":"Front Headlock","technique":"Anaconda Choke","name":"Opponent posts the far hand","reaction":"Opponent posts the far hand to stop the roll and keep the chest off the mat.","response":"Compress the elbow line first, remove the post through angle and then initiate the rotation.","sort":40},{"type":"Submissions","block":"Front Headlock","technique":"D'Arce Choke","name":"Opponent keeps the far elbow tight","reaction":"Opponent closes the far elbow to prevent your arm from threading deep.","response":"Create shoulder separation with pressure and angle before reaching for the lock.","sort":50},{"type":"Submissions","block":"Front Headlock","technique":"Go Behind","name":"Opponent raises the head","reaction":"Opponent lifts the head and starts recovering posture from the front headlock.","response":"Use the head rise to circle behind while keeping control of the near arm or hip.","sort":60},{"type":"Submissions","block":"Front Headlock","technique":"Back Take Transition","name":"Opponent turns away from the choke","reaction":"Opponent rotates the shoulders away to relieve neck pressure.","response":"Follow the rotation, control the far hip and secure the back rather than forcing the choke.","sort":70},{"type":"Submissions","block":"Side Control Attacks","technique":"Crossface Control","name":"Opponent turns toward you","reaction":"Opponent frames and turns the face and knees back toward your torso.","response":"Maintain head-and-shoulder alignment, block the near hip and settle chest pressure before attacking.","sort":10},{"type":"Submissions","block":"Side Control Attacks","technique":"Americana","name":"Opponent straightens the arm","reaction":"Opponent extends the arm to prevent the figure-four from being completed.","response":"Follow the extension into straight-arm control or transition to the next attack instead of forcing the shoulder.","sort":20},{"type":"Submissions","block":"Side Control Attacks","technique":"Kimura","name":"Opponent grips hands together","reaction":"Opponent connects the hands to stop the kimura rotation.","response":"Control the elbow line, change hip angle and break the defensive grip before rotating the shoulder.","sort":30},{"type":"Submissions","block":"Side Control Attacks","technique":"Armbar","name":"Opponent turns the thumb and elbow down","reaction":"Opponent rotates the arm toward the mat to hide the elbow line.","response":"Control above the elbow and adjust the hip angle before sitting into the armbar.","sort":40},{"type":"Submissions","block":"Side Control Attacks","technique":"Paper Cutter Choke","name":"Opponent frames the near shoulder","reaction":"Opponent uses the near forearm to block chest pressure and collar access.","response":"Clear the frame first and establish the collar grip without sacrificing side-control position.","sort":50},{"type":"Submissions","block":"Side Control Attacks","technique":"North-South Transition","name":"Opponent turns away from crossface","reaction":"Opponent rotates away and exposes space above the shoulders.","response":"Follow around the head, control the far hip and settle North-South before attacking.","sort":60},{"type":"Submissions","block":"Mount Attacks","technique":"Mount Control","name":"Opponent bridges explosively","reaction":"Opponent bridges and turns to dislodge your hips from mount.","response":"Widen the base, follow the hip rotation and climb to a stable mount before attacking.","sort":10},{"type":"Submissions","block":"Mount Attacks","technique":"Americana","name":"Opponent straightens the elbow","reaction":"Opponent extends the arm to prevent the bent-arm lock.","response":"Keep shoulder control and transition to straight-arm exposure or S-mount rather than forcing the elbow bend.","sort":20},{"type":"Submissions","block":"Mount Attacks","technique":"Cross-Collar Choke","name":"Opponent blocks the second grip","reaction":"Opponent controls your second hand before it reaches the collar.","response":"Maintain the first deep grip, use posture and angle to clear the hand fight before completing the choke.","sort":30},{"type":"Submissions","block":"Mount Attacks","technique":"Ezekiel Choke","name":"Opponent keeps elbows tight to neck","reaction":"Opponent protects the neck with both hands and elbows inside.","response":"Use chest pressure and hand fighting to open a safe path instead of forcing the forearm across the face.","sort":40},{"type":"Submissions","block":"Mount Attacks","technique":"Armbar","name":"Opponent connects the hands","reaction":"Opponent locks the hands together as you isolate the arm from mount.","response":"Control shoulder position, climb the knees and break the grip only after your hip line is secure.","sort":50},{"type":"Submissions","block":"Mount Attacks","technique":"S-Mount Armbar","name":"Opponent turns onto the side","reaction":"Opponent rotates to one side to hide the elbow and escape flat mount.","response":"Follow the shoulder turn into S-mount, control posture and isolate the arm before sitting back.","sort":60},{"type":"Submissions","block":"North-South Attacks","technique":"North-South Control","name":"Opponent turns onto the side","reaction":"Opponent rotates to one hip to create space for guard recovery.","response":"Block the near hip, keep chest connection and follow the shoulder line before attacking.","sort":10},{"type":"Submissions","block":"North-South Attacks","technique":"North-South Choke","name":"Opponent turns the chin toward you","reaction":"Opponent rotates the chin into the choking side to protect the neck.","response":"Adjust chest position and shoulder pressure to expose the correct neck line before tightening.","sort":20},{"type":"Submissions","block":"North-South Attacks","technique":"Kimura","name":"Opponent hides the elbow close to ribs","reaction":"Opponent clamps the elbow to the torso and prevents separation.","response":"Use body position to open the elbow line before securing the figure-four.","sort":30},{"type":"Submissions","block":"North-South Attacks","technique":"Armbar Transition","name":"Opponent straightens the trapped arm","reaction":"Opponent extends the arm while defending the kimura grip.","response":"Keep shoulder control and follow the extension into the armbar line.","sort":40},{"type":"Submissions","block":"North-South Attacks","technique":"Back Take Transition","name":"Opponent turns away to escape North-South","reaction":"Opponent rotates away and exposes the far shoulder and hip.","response":"Follow the rotation, control the hip and secure back position before releasing upper-body control.","sort":50}]$json$::jsonb;
  v_row jsonb;
  v_type_id uuid;
  v_block_id uuid;
  v_technique_id uuid;
  v_type_name text;
  v_block_name text;
  v_technique_name text;
  v_name text;
  v_reaction text;
  v_response text;
  v_sort integer;
begin
  for v_row in select value from jsonb_array_elements(v_seed) loop
    v_type_name := btrim(v_row ->> 'type');
    v_block_name := btrim(v_row ->> 'block');
    v_technique_name := btrim(v_row ->> 'technique');
    v_name := btrim(v_row ->> 'name');
    v_reaction := btrim(v_row ->> 'reaction');
    v_response := nullif(btrim(v_row ->> 'response'), '');
    v_sort := coalesce((v_row ->> 'sort')::integer, 100);

    select t.id into v_type_id
    from public.coach_curriculum_types t
    where lower(t.name) = lower(v_type_name)
    order by t.is_active desc, t.created_at asc
    limit 1;

    if v_type_id is null then
      raise notice 'ATOM Curriculum V2: skipping situation "%" because type "%" is missing.', v_name, v_type_name;
      continue;
    end if;

    select b.id into v_block_id
    from public.coach_curriculum_blocks b
    where b.type_id = v_type_id
      and lower(b.name) = lower(v_block_name)
    order by b.is_active desc, b.created_at asc
    limit 1;

    if v_block_id is null then
      raise notice 'ATOM Curriculum V2: skipping situation "%" because block "%" is missing.', v_name, v_block_name;
      continue;
    end if;

    select ct.id into v_technique_id
    from public.coach_curriculum_techniques ct
    where ct.block_id = v_block_id
      and lower(ct.name) = lower(v_technique_name)
    order by ct.is_active desc, ct.created_at asc
    limit 1;

    if v_technique_id is null then
      raise notice 'ATOM Curriculum V2: skipping situation "%" because technique "%" is missing.', v_name, v_technique_name;
      continue;
    end if;

    if not exists (
      select 1
      from public.coach_curriculum_situations cs
      where cs.technique_id = v_technique_id
        and lower(cs.name) = lower(v_name)
    ) then
      insert into public.coach_curriculum_situations (
        technique_id, name, opponent_reaction, coaching_response, sort_order, is_active
      ) values (
        v_technique_id, v_name, v_reaction, v_response, v_sort, true
      );
    end if;
  end loop;
end
$atom_curriculum_v2_situations$;

commit;
